//! Routes requests for the key-value API.

use std::convert::Infallible;
use std::sync::Arc;

use bytes::Bytes;
use http_body_util::{BodyExt, Full, LengthLimitError, Limited};
use hyper::body::Incoming;
use hyper::header::{CONTENT_LENGTH, CONTENT_TYPE, HeaderValue};
use hyper::{Method, Request, Response, StatusCode};

use crate::store::KvStore;

/// Largest value accepted by `PUT /kv/<key>`.
pub const MAX_VALUE_BYTES: usize = 1 << 20;

const KV_PREFIX: &str = "/kv/";
const MAX_KEY_LEN: usize = 64;

type Body = Full<Bytes>;

/// Handles one request against the shared store. Never fails: every error maps to a status.
pub async fn handle(
    store: Arc<KvStore>,
    request: Request<Incoming>,
) -> Result<Response<Body>, Infallible> {
    Ok(route(&store, request).await.unwrap_or_else(empty))
}

async fn route(store: &KvStore, request: Request<Incoming>) -> Result<Response<Body>, StatusCode> {
    let path = request.uri().path();
    let method = request.method();

    match path {
        "/health" => {
            require(method, &Method::GET)?;
            Ok(with_type(
                StatusCode::OK,
                "text/plain; charset=utf-8",
                Bytes::from_static(b"ok"),
            ))
        }
        "/kv" => {
            require(method, &Method::GET)?;
            Ok(with_type(
                StatusCode::OK,
                "application/json",
                keys_json(&store.keys()).into(),
            ))
        }
        _ => {
            let key = path.strip_prefix(KV_PREFIX).ok_or(StatusCode::NOT_FOUND)?;
            if !is_valid_key(key) {
                return Err(StatusCode::BAD_REQUEST);
            }
            let key = key.to_owned();
            match *method {
                Method::GET => store
                    .get(&key)
                    .map(|value| with_type(StatusCode::OK, "application/octet-stream", value))
                    .ok_or(StatusCode::NOT_FOUND),
                Method::PUT => {
                    let value = read_body(request).await?;
                    Ok(empty(if store.put(&key, value) {
                        StatusCode::CREATED
                    } else {
                        StatusCode::OK
                    }))
                }
                Method::DELETE => Ok(empty(if store.delete(&key) {
                    StatusCode::NO_CONTENT
                } else {
                    StatusCode::NOT_FOUND
                })),
                _ => Err(StatusCode::METHOD_NOT_ALLOWED),
            }
        }
    }
}

fn require(method: &Method, allowed: &Method) -> Result<(), StatusCode> {
    if method == allowed {
        Ok(())
    } else {
        Err(StatusCode::METHOD_NOT_ALLOWED)
    }
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Keys are restricted to `[A-Za-z0-9_-]`, so no JSON escaping is required.
fn keys_json(keys: &[String]) -> String {
    let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    json.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            json.push(',');
        }
        json.push('"');
        json.push_str(key);
        json.push('"');
    }
    json.push(']');
    json
}

async fn read_body(request: Request<Incoming>) -> Result<Bytes, StatusCode> {
    let declared = request
        .headers()
        .get(CONTENT_LENGTH)
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.trim().parse::<u64>().ok());
    if declared.is_some_and(|len| len > MAX_VALUE_BYTES as u64) {
        return Err(StatusCode::PAYLOAD_TOO_LARGE);
    }

    match Limited::new(request.into_body(), MAX_VALUE_BYTES)
        .collect()
        .await
    {
        Ok(collected) => Ok(collected.to_bytes()),
        Err(err) if err.is::<LengthLimitError>() => Err(StatusCode::PAYLOAD_TOO_LARGE),
        Err(_) => Err(StatusCode::BAD_REQUEST),
    }
}

fn empty(status: StatusCode) -> Response<Body> {
    let mut response = Response::new(Body::default());
    *response.status_mut() = status;
    response
}

fn with_type(status: StatusCode, content_type: &'static str, body: Bytes) -> Response<Body> {
    let mut response = Response::new(Full::new(body));
    *response.status_mut() = status;
    response
        .headers_mut()
        .insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    response
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("a%20b"));
    }

    #[test]
    fn json_listing() {
        assert_eq!(keys_json(&[]), "[]");
        assert_eq!(keys_json(&["a".into(), "b".into()]), r#"["a","b"]"#);
    }
}

//! Entry point: `app <port>` serves the key-value API on 127.0.0.1.

mod handler;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

use crate::store::KvStore;

fn main() -> ExitCode {
    let mut args = std::env::args().skip(1);
    let (Some(port), None) = (args.next(), args.next()) else {
        eprintln!("usage: app <port>");
        return ExitCode::from(2);
    };
    let Ok(port) = port.parse::<u16>() else {
        eprintln!("invalid port: {port}");
        return ExitCode::from(2);
    };

    let runtime = match tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
    {
        Ok(runtime) => runtime,
        Err(err) => {
            eprintln!("failed to start runtime: {err}");
            return ExitCode::FAILURE;
        }
    };
    match runtime.block_on(serve(SocketAddr::from((Ipv4Addr::LOCALHOST, port)))) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("server error: {err}");
            ExitCode::FAILURE
        }
    }
}

async fn serve(addr: SocketAddr) -> std::io::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    let store = Arc::new(KvStore::new());

    loop {
        let (stream, _) = match listener.accept().await {
            Ok(conn) => conn,
            Err(err) => {
                // Transient failures (e.g. too many open files) must not stop the server.
                eprintln!("accept failed: {err}");
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                continue;
            }
        };
        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let service = service_fn(move |req| handler::handle(Arc::clone(&store), req));
            if let Err(err) = http1::Builder::new()
                .serve_connection(TokioIo::new(stream), service)
                .await
            {
                eprintln!("connection error: {err}");
            }
        });
    }
}

//! Thread-safe in-memory store keeping keys in ascending order.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use bytes::Bytes;

#[derive(Debug, Default)]
pub struct KvStore {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl KvStore {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores the value; returns `true` if the key was newly created.
    pub fn put(&self, key: &str, value: Bytes) -> bool {
        self.entries
            .write()
            .unwrap_or_else(PoisonError::into_inner)
            .insert(key.to_owned(), value)
            .is_none()
    }

    pub fn get(&self, key: &str) -> Option<Bytes> {
        self.entries
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .get(key)
            .cloned()
    }

    /// Removes the key; returns `true` if it was present.
    pub fn delete(&self, key: &str) -> bool {
        self.entries
            .write()
            .unwrap_or_else(PoisonError::into_inner)
            .remove(key)
            .is_some()
    }

    /// All keys in ascending order.
    pub fn keys(&self) -> Vec<String> {
        self.entries
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .keys()
            .cloned()
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_delete() {
        let store = KvStore::new();
        assert!(store.put("a", Bytes::from_static(b"1")));
        assert!(!store.put("a", Bytes::from_static(b"2")));
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }

    #[test]
    fn keys_are_sorted() {
        let store = KvStore::new();
        for key in ["b", "a", "c", "B"] {
            store.put(key, Bytes::new());
        }
        assert_eq!(store.keys(), ["B", "a", "b", "c"]);
    }
}
